# -*- coding: utf-8 -*-
"""
ClientExtensions - Standalone version (OANDA removed)
"""


class ClientExtensions:
    """Representation of the ClientExtensions (standalone version)."""

    def __init__(self,
                 clientID=None,
                 clientTag=None,
                 clientComment=None):
        """Instantiate ClientExtensions.

        Parameters
        ----------
        clientID : clientID (optional)
            the clientID
        clientTag : clientTag (optional)
            the clientTag
        clientComment : clientComment (optional)
            the clientComment
        """
        self._data = {}
        
        if clientID:
            self._data.update({"id": clientID})

        if clientTag:
            self._data.update({"tag": clientTag})

        if clientComment:
            self._data.update({"comment": clientComment})

    @property
    def data(self):
        """Return the data dictionary."""
        return self._data


# For backward compatibility with code that expects BaseRequest
class BaseRequest:
    """Empty BaseRequest for compatibility."""
    pass
